
const menu=document.querySelector('.menu'),nav=document.querySelector('nav');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.textContent=open?'Cerrar':'Menú';nav.classList.toggle('open',open)});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.textContent='Menú'}));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav.classList.contains('open')){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.textContent='Menú';menu.focus()}});document.querySelectorAll('details').forEach(d=>d.addEventListener('toggle',()=>{if(d.open)document.querySelectorAll('details').forEach(other=>{if(other!==d)other.open=false})}));

const ecosystemStages=[["01", "Entender", "Primero, la decisión que importa", "Comprendemos el contexto y acordamos qué necesitas decidir.", "El reto de negocio, las fuentes disponibles y las restricciones.", "Una decisión concreta, preguntas priorizadas e hipótesis alternativas.", "Acordar qué necesitamos saber y qué cambiaría con esa evidencia."], ["02", "Diseñar", "Cada método debe tener una razón", "Definimos qué evidencia hace falta y qué métodos aportan a tu pregunta.", "Preguntas, hipótesis, población y condiciones del proyecto.", "Un diseño metodológico y analítico; instrumentos enfocados cuando corresponda.", "Saber qué aporta cada método y qué decisión puede modificar."], ["03", "Generar evidencia", "Información con contexto y calidad", "Conectamos las fuentes acordadas y revisamos su calidad y cobertura.", "Datos, respuestas abiertas y fuentes documentales del proyecto.", "Una base evaluada, con definiciones y limitaciones visibles.", "Distinguir lo que sabemos, lo que falta y lo que requiere revisión."], ["04", "Transformar", "De los datos a una explicación útil", "Analizamos patrones y contrastamos los resultados antes de interpretarlos.", "Evidencia evaluada y preguntas analíticas.", "Segmentos, drivers, temas, modelos o escenarios, según el reto.", "Comprender diferencias y relaciones relevantes, con sus límites."], ["05", "Decidir", "Claridad para comparar alternativas", "Comparamos implicaciones y alternativas con tu equipo.", "Resultados validados, contexto y alternativas de negocio.", "Una lectura ejecutiva y criterios para evaluar opciones.", "Elegir prioridades con evidencia y supuestos explícitos."], ["06", "Activar", "Que el conocimiento entre en uso", "Llevamos los hallazgos a entregables y herramientas que el equipo pueda utilizar.", "Prioridades acordadas y necesidades de uso del equipo.", "Entregables aplicables y una ruta de acción definida con el cliente.", "Facilitar la consulta, alinear al equipo y acompañar la aplicación."], ["07", "Aprender", "La siguiente decisión parte de lo aprendido", "Documentamos aprendizajes y ajustes para orientar el siguiente ciclo.", "Resultados disponibles, uso de los entregables y retroalimentación.", "Aprendizajes, ajustes y nuevas preguntas, respetando la confidencialidad.", "Conservar contexto y evitar comenzar cada proyecto desde cero."]];
const ecosystemTechnology=["Criterio estratégico · Definimos primero la decisión, las incertidumbres y la evidencia necesaria.", "Analytical Strategy · En desarrollo: conecta el brief con hipótesis, evidencia y métodos justificados, con revisión humana.", "Textana · Desarrollo propio para estructurar y clasificar respuestas abiertas, con revisión de resultados. Su uso se acuerda en cada proyecto.", "Analítica aplicada · Segmentación, precios, modelos predictivos y Text Analytics, elegidos por su utilidad para la pregunta.", "Lectura ejecutiva · Comparamos implicaciones y alternativas con el equipo; distinguimos evidencia de supuestos.", "Dashboards y simuladores · Herramientas para consultar resultados y explorar escenarios dentro del alcance acordado.", "Aprendizaje documentado · Conservamos criterios y retroalimentación para el siguiente ciclo; la plataforma privada de clientes es una fase futura."];
document.querySelectorAll('[data-stage]').forEach(button=>button.addEventListener('click',()=>{const stage=ecosystemStages[Number(button.dataset.stage)];document.querySelectorAll('[data-stage]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));const keys=['number','title','description','input','output','use'];const values=['MOMENTO '+stage[0]+' / '+stage[1].toUpperCase(),...stage.slice(2)];keys.forEach((key,i)=>{document.querySelector('[data-eco="'+key+'"]').textContent=values[i]});document.querySelector('[data-eco="technology"]').textContent=ecosystemTechnology[Number(button.dataset.stage)];}));


