const projectStageNames=["Entender", "Diseñar", "Generar evidencia", "Transformar", "Decidir", "Activar", "Aprender"];
let activeProject=0,activeProjectStage=0;
function renderProject(){
 const project=projectCases[activeProject];
 document.querySelectorAll('[data-project]').forEach(button=>button.setAttribute('aria-pressed',String(Number(button.dataset.project)===activeProject)));
 document.querySelectorAll('[data-project-field]').forEach(element=>{element.textContent=project[element.dataset.projectField]});
 document.querySelectorAll('[data-project-stage]').forEach(button=>button.setAttribute('aria-pressed',String(Number(button.dataset.projectStage)===activeProjectStage)));
 document.querySelector('[data-project-stage-status]').textContent=project.stageStatus;
 document.querySelector('[data-project-stage-title]').textContent=String(activeProjectStage+1).padStart(2,'0')+' / '+projectStageNames[activeProjectStage];
 document.querySelector('[data-project-stage-text]').textContent=project.steps[activeProjectStage];
}
document.querySelectorAll('[data-project]').forEach(button=>button.addEventListener('click',()=>{activeProject=Number(button.dataset.project);renderProject()}));
document.querySelectorAll('[data-project-stage]').forEach(button=>button.addEventListener('click',()=>{activeProjectStage=Number(button.dataset.projectStage);renderProject()}));
